package nl.slimov.app;
import android.app.*;import android.content.*;import android.os.*;import android.content.pm.ServiceInfo;import org.json.*;import java.util.concurrent.*;import java.time.*;
/** Explicit foreground journey watch. No private GPS/background-location access. */
public final class WatchService extends Service {
 private final ScheduledExecutorService pool=Executors.newSingleThreadScheduledExecutor();private volatile JSONObject config=new JSONObject();private volatile double along=-1,lastPosition;private long lastTrip,lastFallback,lastReminderTrip;private volatile boolean fired,alive;private String lastRisk="",lastBody="",reminderIdentity="";private final java.util.Set<String> sent=java.util.Collections.synchronizedSet(new java.util.HashSet<>());
 @Override public void onCreate(){super.onCreate();alive=true;pool.scheduleAtFixedRate(()->tick(),0,15,TimeUnit.SECONDS);}
 @Override public synchronized int onStartCommand(Intent intent,int flags,int id){if(intent==null||"stop".equals(intent.getAction())){alive=false;LiveHub.set("monitor","",null);getSharedPreferences("watch",0).edit().remove("config").putBoolean("running",false).apply();stopSelf();return START_NOT_STICKY;}try{config=new JSONObject(intent.getStringExtra("config"));JSONObject r=config.optJSONObject("reminder");String identity=r==null?"":r.optString("tripId")+"|"+r.optInt("target")+"|"+r.optInt("before");if(!identity.equals(reminderIdentity)){along=r==null?-1:r.optDouble("initialAlong",-1);fired=false;lastPosition=0;lastReminderTrip=0;lastFallback=0;reminderIdentity=identity;}getSharedPreferences("watch",0).edit().putBoolean("reminderFired",fired).putString("config",config.toString()).putBoolean("running",true).putLong("heartbeat",System.currentTimeMillis()).apply();startForeground(12,Notice.build(this,"watch","SlimOV bewaakt je reis","Open de app voor je route · stop via deze melding",true),ServiceInfo.FOREGROUND_SERVICE_TYPE_DATA_SYNC);LiveHub.set("monitor",r==null?"":r.optString("owner"),new LiveStream.Listener(){public void positions(JSONArray points,int bytes){handle(points,true);}public void status(String text){}});pool.execute(()->tick());}catch(Exception e){stopSelf();}return START_NOT_STICKY;}
 private synchronized void handle(JSONArray points,boolean direct){JSONObject r=config.optJSONObject("reminder");if(r==null||fired||!alive||!direct&&r.optString("numericTrip").isEmpty()&&r.optString("nsNumber").isEmpty())return;for(int i=0;i<points.length();i++){JSONObject v=points.optJSONObject(i);if(v==null)continue;boolean match=direct?v.optString("lineplanningnumber").equals(r.optString("planning"))&&v.optString("journeynumber").equals(r.optString("journey")):(!r.optString("nsNumber").isEmpty()?v.optString("nsNumber").equals(r.optString("nsNumber")):v.optString("trip").equals(r.optString("numericTrip")))&&(r.has("nsNumber")&&!r.optString("nsNumber").isEmpty()||v.optString("startDate").equals(r.optString("startDate"))&&v.optString("startTime").equals(r.optString("startTime")));if(!match||v.optDouble("timestamp")<lastPosition)continue;try{JSONObject p=WatchLogic.progress(r.getJSONObject("model"),v,along);if(!p.optBoolean("reliable"))continue;HistoryStore.gps(this,r,p,v);lastPosition=v.optDouble("timestamp");along=p.getDouble("along");int target=r.getInt("target"),passed=p.getInt("passed"),before=r.optInt("before",1);if(passed>=target){fired=true;status("Uitstaphalte bereikt; herinnering afgerond");}else if(passed>=Math.max(0,target-before)){fired=true;Notice.send(this,9,"Bijna uitstappen",r.optString("name")+" · nog ongeveer "+(target-passed)+" halte(n) volgens voertuig-GPS");status("Uitstapmelding gegeven");}if(fired){LiveHub.set("monitor","",null);getSharedPreferences("watch",0).edit().putBoolean("reminderFired",true).apply();}}catch(Exception ignored){}}}
 private void status(String body){getSharedPreferences("watch",0).edit().putString("status",body).apply();if(!body.equals(lastBody)){lastBody=body;getSystemService(NotificationManager.class).notify(12,Notice.build(this,"watch","SlimOV · actieve reis",body,true));}}
 private void tick(){if(!alive)return;getSharedPreferences("watch",0).edit().putLong("heartbeat",System.currentTimeMillis()).apply();long now=System.currentTimeMillis();JSONObject r=config.optJSONObject("reminder"),journey=config.optJSONObject("journey");if(r==null&&journey==null)return;
  try{if(r!=null&&!fired&&now-lastReminderTrip>=60000){lastReminderTrip=now;checkObserved(r);}if(r!=null&&!fired&&(!r.optString("numericTrip").isEmpty()||!r.optString("nsNumber").isEmpty())&&now/1000-lastPosition>60&&now-lastFallback>=25000){lastFallback=now;if(!r.optString("nsNumber").isEmpty())handle(TrainApi.positions(MonitorNetwork.ns(this,"/vehicle?features=trein")),false);else handle(MonitorNetwork.vehicles().getJSONArray("vehicles"),false);if(now/1000-lastPosition>120)status("Voertuig-GPS ontbreekt/verouderd · uitstapmelding wacht");}
   if(journey!=null&&now-lastTrip>=60000){lastTrip=now;JSONArray legs=journey.optJSONArray("legs");if(legs==null)return;JSONObject previous=null,previousEvent=null;double walk=0;boolean walkKnown=false;int queried=0;String info="Reisinformatie bijgewerkt";
    for(int i=0;i<legs.length()&&queried<2;i++){JSONObject leg=legs.getJSONObject(i);if(leg.optString("mode").equals("WALK")){walk+=leg.optDouble("duration");walkKnown=true;continue;}if(parse(leg.optString("endTime"))<now-600000)continue;queried++;JSONObject trip=MonitorNetwork.trip(this,leg.getString("tripId"),false),from=WatchLogic.event(trip,leg.getString("tripId"),leg.getJSONObject("from").optString("stopId"),leg.getJSONObject("from").optString("scheduledDeparture"),"departure"),to=WatchLogic.event(trip,leg.getString("tripId"),leg.getJSONObject("to").optString("stopId"),leg.getJSONObject("to").optString("scheduledArrival"),"arrival");
     if(!alive||config.optJSONObject("journey")!=journey)return;HistoryStore.remember(this,trip,leg.getString("tripId"));if(to!=null&&!to.optString("arrival").isEmpty())leg.put("endTime",to.optString("arrival"));if(from!=null&&!from.optString("departure").isEmpty())leg.put("startTime",from.optString("departure"));if(WatchLogic.cancelled(trip,leg.getString("tripId"))||from!=null&&from.optBoolean("cancelled")||to!=null&&to.optBoolean("cancelled")){info="Een rit of halte in je reis vervalt";if(sent.add(leg.optString("tripId")+info))Notice.send(this,13,"Reis gewijzigd",info);lastRisk=info;}
     if(from!=null&&!from.optString("scheduledTrack").isEmpty()&&!from.optString("track").isEmpty()&&!from.optString("track").equals(from.optString("scheduledTrack"))){String message="Perron gewijzigd: "+from.optString("scheduledTrack")+" → "+from.optString("track");if(sent.add(leg.optString("tripId")+message))Notice.send(this,14,"Perron gewijzigd",message);lastRisk=message;}
     if(previousEvent!=null&&from!=null&&walkKnown&&WatchLogic.eventRealtime(previousEvent,"arrival")&&WatchLogic.eventRealtime(from,"departure")){long a=parse(previousEvent.optString("arrival")),b=parse(from.optString("departure"));if(a>0&&b>0){long margin=(long)((b-a)/1000-Math.max(walk,journey.optDouble("extra")*60));info=margin<180?"Overstap krap · controleer je aansluiting":"Overstap waarschijnlijk haalbaar";if(margin<180&&sent.add(leg.optString("tripId")+info))Notice.send(this,10,"Overstapbewaking",info);lastRisk=info;}}else if(previous!=null)info="Overstap: onvoldoende actuele gegevens";previous=leg;previousEvent=to;walk=0;walkKnown=false;
    }status(info);getSharedPreferences("watch",0).edit().putLong("journeyCheckedAt",now).apply();long latestEnd=0;for(int j=0;j<legs.length();j++)latestEnd=Math.max(latestEnd,parse(legs.getJSONObject(j).optString("endTime")));boolean finished=latestEnd>0&&latestEnd<now-600000;if(finished&&(r==null||fired)){status("Reis afgerond volgens bron­tijden");stopSelf();}
   }
  }catch(Exception e){status("Bron tijdelijk niet bereikbaar · laatste reisinfo kan oud zijn");}
  if(fired&&journey==null)stopSelf();
 }
 private void checkObserved(JSONObject r)throws Exception{if(fired)return;JSONObject trip=MonitorNetwork.trip(this,r.getString("tripId"),false);HistoryStore.remember(this,trip,r.getString("tripId"));JSONObject progress=WatchLogic.observedProgress(r.getJSONObject("model"),trip,r.getString("tripId"),r.getInt("target"));applyObserved(r,progress);}
 private synchronized void applyObserved(JSONObject r,JSONObject progress)throws Exception{if(!alive||fired||config.optJSONObject("reminder")!=r)return;int passed=progress.optInt("passed",-1),target=r.getInt("target");if(progress.optBoolean("cancelled")){fired=true;Notice.send(this,9,"Uitstaphalte vervalt",r.optString("name")+" is vervallen volgens de bron. Controleer je reis.");}else if(passed>=target){fired=true;status("Uitstaphalte al bereikt volgens bron");}else if(progress.optBoolean("reliable")&&passed>=Math.max(0,target-r.optInt("before",1))){fired=true;Notice.send(this,9,"Bijna uitstappen",r.optString("name")+" · nog ongeveer "+(target-passed)+" halte(n) volgens geregistreerde haltepassage");}if(fired){LiveHub.set("monitor","",null);getSharedPreferences("watch",0).edit().putBoolean("reminderFired",true).apply();}}
 private static long parse(String s){try{return Instant.parse(s).toEpochMilli();}catch(Exception e){return 0;}}
 @Override public void onTimeout(int id,int type){Notice.send(this,12012,"Reisbewaking gestopt","Android heeft de maximale achtergrondduur bereikt. Open SlimOV om opnieuw te starten.");stopSelf();}
 @Override public void onDestroy(){alive=false;LiveHub.set("monitor","",null);pool.shutdownNow();getSharedPreferences("watch",0).edit().putBoolean("running",false).apply();stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
 @Override public IBinder onBind(Intent intent){return null;}
}
